 const unit=officer(selectedMapOfficerId);if(!unit){card.classList.add('hidden');if(card.innerHTML){card.innerHTML='';card.dataset.renderKey='';}return;}
 const battery=Number.isFinite(Number(unit.battery))?Math.max(0,Math.min(100,Number(unit.battery))):null,coords=Number.isFinite(unit.lat)&&Number.isFinite(unit.lng)?`${Number(unit.lat).toFixed(5)}, ${Number(unit.lng).toFixed(5)}`:'No GPS fix',unitSite=site(unit.siteId)?.name||'Unassigned',accuracy=Number.isFinite(Number(unit.accuracy))?`±${Math.round(Number(unit.accuracy))} m`:'—',signalText=unit.online?'Connected':'Last seen '+ago(unit.lastSeen),signature=JSON.stringify([unit.id,unit.callSign,unit.name,status(unit),unitSite,battery,unit.signal,signalText,accuracy,mapUnitColor(unit)]);
 if(card.dataset.renderKey!==signature){card.innerHTML=`<div class="map-unit-head"><span class="map-unit-status" style="--unit-color:${mapUnitColor(unit)}"></span><div class="map-unit-title"><b>${esc(unit.callSign)} · ${esc(unit.name)}</b><small>${esc(status(unit))} · ${esc(unitSite)}</small></div><button class="map-unit-close" data-action="close-map-unit" aria-label="Close unit details">×</button></div><div class="map-unit-metrics"><div class="map-unit-metric"><small>Battery</small><b>${battery===null?'—':`${Math.round(battery)}%`}</b>${battery===null?'':`<span class="map-unit-battery-track"><i style="width:${battery}%"></i></span>`}</div><div class="map-unit-metric"><small>Signal</small><b>${esc(unit.signal??'—')}</b><span>${esc(signalText)}</span></div><div class="map-unit-metric"><small>GPS accuracy</small><b>${accuracy}</b><span class="map-unit-coordinate">${esc(coords)}</span></div></div><div class="map-unit-actions"><button class="button small ghost" onclick="window.quickMessage('${esc(unit.id)}')">Message</button><button class="button small primary" data-action="focus-unit" data-id="${esc(unit.id)}">Locate unit</button></div>`;card.dataset.renderKey=signature;}
