async function renderBackups(){try{let rows=await api('/api/backups');$('#backupTable').innerHTML=rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Backup file</th><th>Created</th><th>Size</th><th></th></tr></thead><tbody>${rows.map(b=>`<tr><td><b>${esc(b.file)}</b></td><td>${fmt(b.modifiedAt,{year:'numeric',month:'short',day:'2-digit',hour:'2-digit',minute:'2-digit'})}</td><td>${Math.ceil(b.size/1024)} KB</td><td><button class="mini-action" data-action="restore" data-file="${esc(b.file)}">Restore</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">No backups yet.</div>';}catch{}}
async function renderUsers(){try{const d=await api('/api/auth/users'),rows=d.users||[];$('#userTable').innerHTML=rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Account</th><th>Role</th><th>State</th></tr></thead><tbody>${rows.map(u=>`<tr><td><b>${esc(u.name||u.email)}</b><br>${esc(u.email)}</td><td>${esc(u.role)}</td><td>Provisioned</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">No accounts found.</div>';}catch(e){const n=$('#userTable');if(n)n.innerHTML=`<div class="empty-state">${esc(e.message)}</div>`;}}
function fieldHtml(){const f=officer(fieldId)||S.officers[0];if(!f)return header('Field radio','No terminals exist.','＋ Add officer','add-officer');fieldId=f.id;const voice=[...rtcSessions.values()].find(s=>(s.role==='callee'&&s.fieldMic)||(s.role==='caller'&&currentPage==='field'));return `<section class="page-head"><div><div class="eyebrow">OFFICER TERMINAL · LOCAL DEMO <span class="live-pill"><i></i> ${f.online?'CONNECTED':'OFFLINE'}</span></div><h1>Field radio</h1><p>Mobile-friendly officer controls · authenticated access required.</p></div><div class="head-actions"><select id="fieldOfficer" class="select">${S.officers.map(o=>`<option value="${o.id}" ${o.id===f.id?'selected':''}>${esc(o.callSign)} · ${esc(o.name)}</option>`).join('')}</select></div></section><div class="workspace-grid"><div class="content-card"><div class="panel-heading"><div><div class="panel-title">${esc(f.callSign)} · ${esc(f.name)}</div><div class="panel-subtitle">${esc(site(f.siteId)?.name||'No assigned post')} · ${status(f)}</div></div><span class="tag ${cls(f)}">${esc(status(f))}</span></div><div class="modal-body"><div class="kv-grid"><div class="kv-card"><small>Shift</small><b style="font-size:14px">${f.shiftId?'Clocked in':'Off duty'}</b></div><div class="kv-card"><small>Battery</small><b>${f.battery??'—'}%</b></div><div class="kv-card"><small>GPS accuracy</small><b>±${f.accuracy||'—'}m</b></div></div><div class="toolbar" style="border:0;padding:10px 0"><button class="button ${f.shiftId?'ghost':'primary'}" data-action="field-clock">${f.shiftId?'Clock out':'Clock in'}</button><button class="button danger" data-action="field-sos" ${!f.shiftId||f.stunned?'disabled':''}>⚠ SOS</button><button class="button ghost" data-action="field-gps" ${!f.shiftId||f.stunned?'disabled':''}>⌖ Share location</button><button class="button ghost" data-action="field-ptt" ${!f.shiftId||f.stunned?'disabled':''}>◖ ${voice?(voice.stream?.getAudioTracks()?.[0]?.enabled?'Mute mic':'Push to talk'):'Call control'}</button>${voice?`<button class="button danger" data-action="voice-end" data-id="${esc(voice.callId)}">End voice</button>`:''}</div><div class="panel-footer">Location tracking runs only while clocked in. Grant browser location permission to share GPS. SOS queues locally when disconnected.</div></div></div><div class="content-card"><div class="panel-heading"><div><div class="panel-title">My messages</div><div class="panel-subtitle">Private dispatch messages for this terminal</div></div></div><div id="fieldMessages" class="detail-list"></div><div class="toolbar"><textarea id="fieldReply" class="textarea" placeholder="Message control room…" ${!f.shiftId||f.stunned?'disabled':''}></textarea><button class="button primary small" data-action="field-reply" ${!f.shiftId||f.stunned?'disabled':''}>Send</button></div></div><div class="content-card workspace-full"><div class="panel-heading"><div><div class="panel-title">Radio controls</div><div class="panel-subtitle">Group · ${esc(f.group)} · Location interval ${f.config?.locationInterval||S.settings.locationInterval}s</div></div><button class="button ghost small" data-action="field-break" ${!f.shiftId?'disabled':''}>${f.status==='on-break'?'End break':'Start break'}</button></div><div class="detail-list"><div class="detail-row"><span>Connection</span><b>${navigator.onLine?'Online':'Offline'} · last contact ${ago(f.lastSeen)}</b></div><div class="detail-row"><span>Device state</span><b>${f.stunned?'Radio stunned — transmit disabled':'Ready'}</b></div><div class="detail-row"><span>Queued offline events</span><b>${pendingEvents().length}</b></div></div></div></div>`;}
function renderField(){const f=officer(fieldId);if(f?.shiftId&&!f.stunned)startGPS();else stopGPS();if((!f?.shiftId||f.stunned)&&rtcSessions.size)for(const cid of [...rtcSessions.keys()]){endVoiceCall(cid,true);api('/api/action',{method:'POST',body:JSON.stringify({type:'call-end',id:cid})}).catch(()=>{});}$('#fieldOfficer').onchange=e=>{stopGPS();lastLocationPush=0;fieldId=e.target.value;renderPage();rtcRegister().catch(()=>{});};const ms=f.stunned?[]:S.messages.filter(m=>Boolean(m.deliveredAt)&&(m.to===f.id||m.to==='all'||m.group===f.group));$('#fieldMessages').innerHTML=ms.length?ms.slice(0,12).map(m=>`<div class="detail-row"><span><b>${esc(m.from)}</b><small style="display:block;color:#87928b;margin-top:4px">${esc(m.body)}</small></span><b>${fmt(m.createdAt)}</b></div>`).join(''):'<div class="empty-state">No messages</div>';}
function pendingEvents(){try{return JSON.parse(localStorage.getItem('dispatchQueue')||'[]')}catch{return[]}}
function queueEvent(event){const q=pendingEvents();q.push(event);localStorage.setItem('dispatchQueue',JSON.stringify(q));flushQueue();}

function getVoicePeerId(){if(rtcPeerId)return rtcPeerId;try{rtcPeerId=sessionStorage.getItem('dispatchVoicePeer')||'';if(!rtcPeerId){rtcPeerId=crypto.randomUUID();sessionStorage.setItem('dispatchVoicePeer',rtcPeerId);}}catch{rtcPeerId=`peer-${Math.random().toString(36).slice(2)}-${Date.now()}`;}return rtcPeerId;}
async function rtcRegister(){if(!S)return;const role=currentPage==='field'?'field':'control',f=role==='field'?officer(fieldId):null;return api('/api/rtc/register',{method:'POST',body:JSON.stringify({peerId:getVoicePeerId(),role,officerId:f?.id,label:f?.callSign||'Dispatch control'})});}
function startRtcAgent(){if(rtcPollTimer)return;rtcRegister().catch(()=>{});rtcPollTimer=setInterval(rtcHeartbeat,1000);}
async function rtcHeartbeat(){if(rtcPollBusy||!S)return;rtcPollBusy=true;try{await rtcRegister();const d=await api(`/api/rtc/poll?peer=${encodeURIComponent(getVoicePeerId())}`);for(const m of d.messages||[])await handleVoiceSignal(m);}catch{}finally{rtcPollBusy=false;}}
async function sendVoiceSignal(toPeer,callId,type,payload={}){return api('/api/rtc/signal',{method:'POST',body:JSON.stringify({fromPeer:getVoicePeerId(),toPeer,callId,type,payload})});}
function makeVoicePeer(session,remote){
  const pc=new RTCPeerConnection({iceServers:[]}),conn={peer:remote,pc,ready:false,localIce:[],remoteIce:[]};session.connections.set(remote.peerId,conn);
  if(session.stream)for(const track of session.stream.getTracks())pc.addTrack(track,session.stream);else if(session.receiveOnly)pc.addTransceiver('audio',{direction:'recvonly'});
  pc.onicecandidate=e=>{if(!e.candidate)return;if(conn.ready)sendVoiceSignal(remote.peerId,session.callId,'ice',{candidate:e.candidate}).catch(()=>{});else conn.localIce.push(e.candidate);};
  pc.ontrack=e=>{let audio=session.audioEls.get(remote.peerId);if(!audio){audio=document.createElement('audio');audio.autoplay=true;audio.playsInline=true;audio.setAttribute('aria-label','Live dispatch audio');audio.style.cssText='position:fixed;width:1px;height:1px;opacity:.01;pointer-events:none;left:-10px;bottom:-10px';document.body.append(audio);session.audioEls.set(remote.peerId,audio);}audio.srcObject=e.streams[0]||new MediaStream([e.track]);audio.play().catch(()=>toast('Tap the page once to enable incoming audio.',true));};
  pc.onconnectionstatechange=()=>{if(pc.connectionState==='connected'){toast(`Voice linked · ${remote.label||'terminal'}`);const call=S.calls.find(c=>c.id===session.callId);if(call&&currentPage==='calls')renderCalls();}else if(pc.connectionState==='failed'){toast('Voice link failed. Use localhost/HTTPS, permit the microphone, and check peer connectivity.',true);}};
  return conn;
}
async function startLiveVoiceCall(callId,peers,options={}){
  if(!window.RTCPeerConnection||(!options.receiveOnly&&!navigator.mediaDevices?.getUserMedia))throw Error('Live voice requires WebRTC and microphone permission in a secure browser context.');
  const stream=options.receiveOnly?null:await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}}),session={callId,role:'caller',stream,receiveOnly:Boolean(options.receiveOnly),connections:new Map(),audioEls:new Map()};rtcSessions.set(callId,session);
  try{for(const peer of peers){const conn=makeVoicePeer(session,peer);conn.pc._dispatchCallId=callId;const offer=await conn.pc.createOffer();await conn.pc.setLocalDescription(offer);await sendVoiceSignal(peer.peerId,callId,'offer',{description:conn.pc.localDescription,fromLabel:currentPage==='field'?officer(fieldId)?.callSign||'Field unit':'Dispatch control',channel:1,participant:currentPage==='field'?fieldId:'control',receiveOnly:Boolean(session.receiveOnly)});conn.ready=true;const candidates=conn.localIce.splice(0);for(const c of candidates)await sendVoiceSignal(peer.peerId,callId,'ice',{candidate:c});}setTimeout(async()=>{const call=S?.calls.find(c=>c.id===callId);if(call?.status==='ringing'&&rtcSessions.has(callId)){await closeVoiceCall(callId,true);await api('/api/action',{method:'POST',body:JSON.stringify({type:'call-fail',id:callId,reason:'No answer after 30 seconds'})}).catch(()=>{});await refresh();toast('No answer · voice call ended',true);}},30000);return session;}catch(e){await closeVoiceCall(callId,false);throw e;}
}
async function acceptLiveVoiceOffer(message){
  const {callId,fromPeer,payload}=message;if(!navigator.mediaDevices?.getUserMedia)throw Error('Microphone unavailable. Use localhost/HTTPS and allow microphone access.');
  const stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}}),session={callId,role:'callee',stream,connections:new Map(),audioEls:new Map(),fieldMic:currentPage==='field'};rtcSessions.set(callId,session);
  const remote={peerId:fromPeer,label:payload.fromLabel||'Dispatch control'},conn=makeVoicePeer(session,remote);conn.pc._dispatchCallId=callId;await conn.pc.setRemoteDescription(new RTCSessionDescription(payload.description));
  if(session.fieldMic&&!payload.receiveOnly)stream.getAudioTracks().forEach(t=>t.enabled=false);
  const pending=rtcPendingIce.get(`${callId}:${fromPeer}`)||[];rtcPendingIce.delete(`${callId}:${fromPeer}`);for(const c of pending)try{await conn.pc.addIceCandidate(new RTCIceCandidate(c));}catch{}
  const answer=await conn.pc.createAnswer();await conn.pc.setLocalDescription(answer);await sendVoiceSignal(fromPeer,callId,'answer',{description:conn.pc.localDescription,participant:currentPage==='field'?fieldId:'control',label:currentPage==='field'?officer(fieldId)?.callSign||'Field unit':'Dispatch control'});conn.ready=true;for(const c of conn.localIce.splice(0))await sendVoiceSignal(fromPeer,callId,'ice',{candidate:c});
  await action('call-answer',{id:callId,participant:currentPage==='field'?fieldId:'control'});toast('Live voice channel connected.');
}
async function handleVoiceSignal(m){
  const key=`${m.callId}:${m.fromPeer}`;
  if(m.type==='offer'){
    if(rtcPendingOffers.has(key)||rtcSessions.has(m.callId))return;rtcPendingOffers.set(key,m);
    openModal('Incoming live voice call',`<p><b>${esc(m.payload.fromLabel||'Dispatch control')}</b> is calling on channel ${esc(m.payload.channel||1)}.</p><p class="form-help">This is a live browser audio link. Allow microphone access to answer. Audio is not recorded unless you separately start a recording.</p><button type="button" class="button ghost" data-action="voice-decline" data-id="${esc(m.callId)}" data-peer="${esc(m.fromPeer)}">Decline call</button>`,'Accept call',async()=>{try{await acceptLiveVoiceOffer(m);rtcPendingOffers.delete(key);$('#modalRoot').innerHTML='';}catch(e){rtcPendingOffers.delete(key);toast(`Could not answer: ${e.message}`,true);}});return;
  }
  if(m.type==='answer'){
    const session=rtcSessions.get(m.callId),conn=session?.connections.get(m.fromPeer);if(!conn)return;await conn.pc.setRemoteDescription(new RTCSessionDescription(m.payload.description));const queued=conn.remoteIce.splice(0);for(const c of queued)try{await conn.pc.addIceCandidate(new RTCIceCandidate(c));}catch{}await action('call-answer',{id:m.callId,participant:m.payload.participant||m.fromPeer});return;
  }
  if(m.type==='ice'){
    const conn=rtcSessions.get(m.callId)?.connections.get(m.fromPeer);if(!conn){const list=rtcPendingIce.get(key)||[];list.push(m.payload.candidate);rtcPendingIce.set(key,list);return;}if(conn.pc.remoteDescription)try{await conn.pc.addIceCandidate(new RTCIceCandidate(m.payload.candidate));}catch{}else conn.remoteIce.push(m.payload.candidate);return;
  }
  if(m.type==='reject'){const s=rtcSessions.get(m.callId);if(s){const c=s.connections.get(m.fromPeer);c?.pc.close();s.connections.delete(m.fromPeer);if(!s.connections.size){await closeVoiceCall(m.callId,false);await api('/api/action',{method:'POST',body:JSON.stringify({type:'call-fail',id:m.callId,reason:'Recipient declined the call'})});await refresh();}}toast('Call declined by recipient',true);return;}
  if(m.type==='hangup'){if(rtcPendingOffers.has(key)){rtcPendingOffers.delete(key);$('#modalRoot').innerHTML='';}await closeVoiceCall(m.callId,false);try{await action('call-end',{id:m.callId});}catch{}toast('Remote party ended the voice call.');}
}
async function closeVoiceCall(callId,notify=true){const session=rtcSessions.get(callId);if(session){if(notify)for(const conn of session.connections.values())sendVoiceSignal(conn.peer.peerId,callId,'hangup',{}).catch(()=>{});for(const conn of session.connections.values())conn.pc.close();for(const a of session.audioEls.values()){a.pause();a.srcObject=null;a.remove();}session.stream?.getTracks().forEach(t=>t.stop());rtcSessions.delete(callId);}for(const key of [...rtcPendingIce.keys()])if(key.startsWith(`${callId}:`))rtcPendingIce.delete(key);for(const key of [...rtcPendingOffers.keys()])if(key.startsWith(`${callId}:`))rtcPendingOffers.delete(key);}
async function startFieldVoiceCall(){const peers=await api(`/api/rtc/peers?role=control&exclude=${encodeURIComponent(getVoicePeerId())}`);if(!peers.peers?.length)throw Error('Open the controller in another tab; no control-room voice client is online.');const d=await action('call-start',{callType:'intercom',from:officer(fieldId)?.callSign||'Field unit',to:'control',participantIds:[fieldId],live:true});try{await startLiveVoiceCall(d.call,peers.peers);render();}catch(e){await api('/api/action',{method:'POST',body:JSON.stringify({type:'call-fail',id:d.call,reason:e.message})});await refresh();throw e;}}
async function requestRemoteVoiceMonitor(officerId){const unit=officer(officerId);if(!unit?.shiftId||unit.stunned)throw Error('Selected terminal is not clocked in and available.');const result=await api(`/api/rtc/peers?officerId=${encodeURIComponent(officerId)}&exclude=${encodeURIComponent(getVoicePeerId())}`);if(!result.peers?.length)throw Error('No active Field app is connected for this terminal.');const d=await action('call-start',{callType:'monitor',from:'Control room',to:unit.id,participantIds:[unit.id],live:true});try{await startLiveVoiceCall(d.call,result.peers,{receiveOnly:true});toast(`Remote voice request sent to ${unit.callSign}; it must be accepted on the Field app.`);}catch(e){await api('/api/action',{method:'POST',body:JSON.stringify({type:'call-fail',id:d.call,reason:e.message})});await refresh();throw e;}}
async function togglePushToTalk(){if(currentPage==='field'){const f=officer(fieldId);if(!f?.shiftId||f.stunned)return toast('Clock in and be active before using voice',true);}let session=[...rtcSessions.values()].find(x=>x.role==='callee'&&x.fieldMic)||[...rtcSessions.values()].find(x=>x.role==='caller'&&currentPage==='field');if(!session){try{await startFieldVoiceCall();toast('Calling control room. Answer in the controller tab.');}catch(e){toast(e.message,true);}return;}const tracks=session.stream?.getAudioTracks()||[];if(!tracks.length)return toast('No microphone track is active',true);const enabled=!tracks[0].enabled;tracks.forEach(t=>t.enabled=enabled);const btn=$('#pageContent [data-action="field-ptt"]');if(btn)btn.innerHTML=`◖ ${enabled?'Mute mic':'Push to talk'}`;toast(enabled?'Push-to-talk microphone open':'Push-to-talk microphone muted');}
async function endVoiceCall(callId,notify=true){await closeVoiceCall(callId,notify);}
async function flushQueue(){if(!navigator.onLine)return;let q=pendingEvents();while(q.length){const e=q[0];try{if(e.kind==='location')await api('/api/ingest/location',{method:'POST',body:JSON.stringify(e.payload)});else await api('/api/action',{method:'POST',body:JSON.stringify(e.payload)});q.shift();localStorage.setItem('dispatchQueue',JSON.stringify(q));}catch{return;}}refresh();}
function startGPS(){if(window.DispatchNative?.startTracking){const f=officer(fieldId);if(f?.shiftId&&!f.stunned)window.DispatchNative.startTracking(f.id,Number(f.config?.locationInterval||S.settings.locationInterval||15));return;}if(gpsWatch!==null||!navigator.geolocation)return;gpsWatch=navigator.geolocation.watchPosition(pos=>{const f=officer(fieldId);if(!f?.shiftId)return;const interval=Number(f.config?.locationInterval||S.settings.locationInterval||15)*1000;if(Date.now()-lastLocationPush<interval)return;lastLocationPush=Date.now();const payload={officerId:f.id,lat:pos.coords.latitude,lng:pos.coords.longitude,accuracy:pos.coords.accuracy,timestamp:new Date().toISOString(),eventId:`${f.id}-${pos.timestamp}`};queueEvent({kind:'location',payload});},e=>toast(`Location unavailable: ${e.message}`,true),{enableHighAccuracy:true,maximumAge:5000,timeout:15000});toast('Location sharing active while clocked in.');}
function stopGPS(){window.DispatchNative?.stopTracking?.();if(gpsWatch!==null&&navigator.geolocation){navigator.geolocation.clearWatch(gpsWatch);gpsWatch=null;}}
function openModal(title,body,submit='Save',fn){const root=$('#modalRoot');root.innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-head"><h2>${title}</h2><button class="modal-close" data-close>×</button></div><form id="modalForm"><div class="modal-body">${body}</div><div class="modal-foot"><button type="button" class="button ghost" data-close>Cancel</button>${fn?`<button class="button primary">${submit}</button>`:`<button type="button" class="button primary" data-close>${submit}</button>`}</div></form></div></div>`;root.querySelectorAll('[data-close]').forEach(x=>x.onclick=()=>root.innerHTML='');root.querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))root.innerHTML='';};root.querySelector('#modalForm').onsubmit=async e=>{e.preventDefault();await fn?.(new FormData(e.currentTarget));};}
