function siteForm(s=null,coords=null){let p=coords||s?.coordinates||[[-26.1038,28.0535],[-26.1038,28.0555],[-26.106,28.0555],[-26.106,28.0535]];openModal(s?'Edit site':'Create geofence site',`<div class="form-grid">${fld('Site name','name',s?.name||'New post')}<div class="form-field"><label>Area type</label><select class="select" name="areaType"><option value="work" ${s?.areaType!=='restricted'?'selected':''}>Work site</option><option value="restricted" ${s?.areaType==='restricted'?'selected':''}>Restricted area</option></select></div>${fld('Boundary tolerance (metres)','tolerance',s?.tolerance||40,'number')}<div class="form-field"><label>Colour</label><input class="input" name="color" type="color" value="${esc(s?.color||'#648b73')}"></div><div class="form-field full"><label>Assigned officers (optional)</label><select class="select" name="assigned" multiple style="height:85px">${S.officers.map(o=>`<option value="${o.id}" ${s?.assigned?.includes(o.id)?'selected':''}>${esc(o.callSign)} · ${esc(o.name)}</option>`).join('')}</select></div><div class="form-field full"><label>Boundary [latitude, longitude] pairs</label><textarea class="textarea" name="coordinates">${JSON.stringify(p)}</textarea><span class="form-help">Work zones link units to posts and track arrivals/departures. Restricted zones mark prohibited areas and can trigger geofence alerts.</span></div></div>`,'Save site',async fd=>{let coordinates;try{coordinates=JSON.parse(fd.get('coordinates'));}catch{toast('Invalid boundary coordinates',true);return;}const assigned=[...$('#modalRoot [name=assigned]').selectedOptions].map(x=>x.value);await action('site-save',{id:s?.id,name:fd.get('name'),areaType:fd.get('areaType'),tolerance:+fd.get('tolerance'),color:fd.get('color'),coordinates,assigned});$('#modalRoot').innerHTML='';});}
function regionForm(r=null){openModal(r?'Edit geofenced zone':'Add geofenced zone',`<div class="form-grid">${fld('Zone name','name',r?.name||'Restricted area')}<div class="form-field"><label>Type</label><select class="select" name="areaType"><option value="work" ${r?.areaType!=='restricted'?'selected':''}>Working area</option><option value="restricted" ${r?.areaType==='restricted'?'selected':''}>Restricted area</option></select></div><div class="form-field full"><label>Boundary [latitude, longitude] pairs</label><textarea class="textarea" name="coordinates">${JSON.stringify(r?.coordinates||[[-26.1038,28.0535],[-26.1038,28.0555],[-26.106,28.0555]])}</textarea><span class="form-help">Drag the zone vertices on the map or edit coordinates. Work zones track post arrivals/departures; restricted zones can trigger geofence alerts.</span></div></div>`,r?'Save zone':'Save zone',async fd=>{try{const coordinates=JSON.parse(fd.get('coordinates'));if(!Array.isArray(coordinates)||coordinates.length<3||coordinates.some(p=>!Array.isArray(p)||p.length<2||!Number.isFinite(Number(p[0]))||!Number.isFinite(Number(p[1]))))throw new Error('Invalid boundary');await action('region-save',{id:r?.id,name:fd.get('name'),areaType:fd.get('areaType'),coordinates,assigned:r?.assigned||[]});$('#modalRoot').innerHTML='';}catch{toast('Enter at least three valid boundary coordinates',true);}});}
