function startDrawing(page=false){drawPoints=[];if(page&&siteMap){let line;const click=e=>{drawPoints.push([e.latlng.lat,e.latlng.lng]);if(line)line.remove();line=L.polyline(drawPoints,{color:'#285442',dashArray:'5 4'}).addTo(siteMap);};siteMap.on('click',click);siteMap.once('dblclick',()=>{siteMap.off('click',click);siteMap.off('dblclick');if(drawPoints.length>=3)siteForm(null,[...drawPoints]);else toast('Draw at least 3 points',true);});toast('Click map vertices; double-click to finish.');return;}if(!map)return;drawMode=true;$('#drawHint').classList.remove('hidden');toast('Click map vertices, then finish the boundary.');}
async function startRecording(){
  if(!navigator.mediaDevices?.getUserMedia)return toast('Microphone recording requires a secure browser context and microphone permission.',true);
  let stream;try{stream=await navigator.mediaDevices.getUserMedia({audio:true});}catch(e){return toast(`Microphone unavailable: ${e.message}`,true);}
  if(!confirm('Record this microphone locally for up to 30 seconds? Obtain participant consent before recording.')){stream.getTracks().forEach(t=>t.stop());return;}
  const call=S.calls.find(c=>c.status==='active'&&c.live),mr=new MediaRecorder(stream),parts=[];mr.ondataavailable=e=>{if(e.data.size)parts.push(e.data);};mr.onerror=()=>toast('Audio recording failed',true);mr.onstop=()=>{stream.getTracks().forEach(t=>t.stop());const blob=new Blob(parts,{type:mr.mimeType||'audio/webm'});if(blob.size>2e6){toast('Recording exceeds the local demo 2 MB cap',true);return;}const rd=new FileReader();rd.onload=()=>action('recording-save',{callId:call?.id||null,name:`Microphone clip · ${new Date().toLocaleString()}`,mime:blob.type,data:rd.result,duration:Math.round((Date.now()-mr.startAt)/1000),from:currentPage==='field'?officer(fieldId)?.callSign:'Control'});rd.readAsDataURL(blob);};mr.startAt=Date.now();mr.start();toast('Local microphone recording started; automatic stop in 30 seconds.');setTimeout(()=>{if(mr.state==='recording')mr.stop();},30000);
}
function exportCsv(type){const rows=currentPage==='reports'&&currentReportRows.length?currentReportRows:null;if(!rows){location.href=`/api/export?type=${encodeURIComponent(type)}&format=csv`;return;}const keys=[...new Set(rows.flatMap(r=>Object.keys(r)))],cell=v=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return `"${s.replaceAll('"','""')}"`},csv=[keys.map(cell).join(','),...rows.map(r=>keys.map(k=>cell(r[k])).join(','))].join('\r\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=`dispatch-${type}-${dateKey(Date.now())}.csv`;a.click();URL.revokeObjectURL(a.href);}
