function importCsv(){const i=document.createElement('input');i.type='file';i.accept='.csv,text/csv';i.onchange=async()=>{const lines=(await i.files[0].text()).trim().split(/\r?\n/),head=lines.shift().split(',');const officers=lines.map(l=>Object.fromEntries(l.split(',').map((x,j)=>[head[j],x])));await action('import',{officers});};i.click();}
function uploadAudio(){const i=document.createElement('input');i.type='file';i.accept='audio/*';i.onchange=()=>{const f=i.files[0];if(f.size>2e6)return toast('Audio must be less than 2 MB',true);const r=new FileReader();r.onload=()=>action('recording-save',{name:f.name,mime:f.type,data:r.result});r.readAsDataURL(f);};i.click();}
