function syncMapLibreTrafficLayer(){if(!mapLibre||!mapLibreReady)return;const wanted=trafficOn&&trafficConfigured(S.settings)&&S.settings.trafficProvider!=='here',source=mapLibre.getSource('live-traffic');if(wanted&&!source){mapLibre.addSource('live-traffic',{type:'raster',tiles:[trafficTilesUrl()],tileSize:256,attribution:'Traffic © TomTom'});const layer={id:'live-traffic-layer',type:'raster',source:'live-traffic',paint:{'raster-opacity':.95}},before=mapLibre.getLayer('road-casing')?'road-casing':undefined;mapLibre.addLayer(layer,before);}else if(!wanted&&source){if(mapLibre.getLayer('live-traffic-layer'))mapLibre.removeLayer('live-traffic-layer');mapLibre.removeSource('live-traffic');}}
function traffic(enable){
  trafficOn=Boolean(enable);syncTrafficButton();
  if(trafficLayer){trafficLayer.remove();trafficLayer=null;}
  if(!trafficOn){if(mapMode==='3d'&&mapLibreReady){syncMapLibreTrafficLayer();refreshMapLibre();}setTrafficStatus(trafficConfigured(S.settings)?'Live traffic is off':'Traffic key required · Configure in Settings');return;}
  if(!trafficConfigured(S.settings)){trafficOn=false;syncTrafficButton();toast('Configure a TomTom API key in Settings for real traffic',true);setTrafficStatus('Traffic key required · Configure in Settings','error');return;}
  if(S.settings.trafficProvider==='here'){trafficOn=false;syncTrafficButton();toast('HERE traffic overlay is not yet implemented; choose TomTom.',true);setTrafficStatus('Choose TomTom Traffic in Settings','error');return;}
  setTrafficStatus('Loading TomTom live traffic…','loading');
  sampleTraffic();
  const tiles=trafficTilesUrl();
  if(mapMode==='3d'){syncMapLibreTrafficLayer();if(mapLibreReady)refreshMapLibre();}
  else if(map){trafficLayer=L.tileLayer(tiles,{opacity:.95,attribution:'Traffic © TomTom',maxZoom:20});trafficLayer.on('tileload',()=>setTrafficStatus('TomTom live traffic tiles loaded','ok'));trafficLayer.on('tileerror',()=>{window.DispatchDiagnostics?.record('map.traffic.tile.error',{mode:'2d',provider:'TomTom'});setTrafficStatus('TomTom traffic tiles failed · check API access and network','error');});trafficLayer.addTo(map);}
}
