let trafficSampling=false,lastTrafficErrorAt=0;
async function sampleTraffic(force=false){if(trafficSampling||!trafficConfigured(S?.settings)||S.settings.trafficProvider==='here')return;trafficSampling=true;let changed=false;try{for(const site of S.sites.filter(x=>x.areaType==='work')){const latest=latestTraffic(site.id);if(!force&&latest&&Date.now()-Date.parse(latest.at)<5*60000)continue;const result=await api('/api/traffic/sample',{method:'POST',body:JSON.stringify({siteId:site.id,force})});changed=changed||Boolean(result.sampled);}if(changed)await refresh();}catch(e){if(Date.now()-lastTrafficErrorAt>60000){toast(`Live traffic unavailable: ${e.message}`,true);lastTrafficErrorAt=Date.now();setTrafficStatus(`TomTom traffic unavailable · ${e.message}`,'error');}}finally{trafficSampling=false;}}
function geojsonSites(){const feature=(zone,kind)=>{let ring=zone.coordinates.map(p=>[p[1],p[0]]);if(ring.length&&!((ring[0][0]===ring.at(-1)[0])&&(ring[0][1]===ring.at(-1)[1])))ring=[...ring,ring[0]];const t=kind==='site'?latestTraffic(zone.id):null,color=zone.areaType==='restricted'?(zone.color||'#c65b51'):t?trafficColor(t.level):(zone.color||'#648b73');return {type:'Feature',geometry:{type:'Polygon',coordinates:[ring]},properties:{id:zone.id,kind,name:zone.name,type:zone.areaType,color,traffic:t?.level||'',speed:t?.currentSpeed??'',free:t?.freeFlowSpeed??''}};};return {type:'FeatureCollection',features:[...S.sites.map(s=>feature(s,'site')),...S.regions.map(r=>feature(r,'region'))]};}
function geojsonUnits(){return {type:'FeatureCollection',features:S.officers.filter(o=>Number.isFinite(o.lat)&&Number.isFinite(o.lng)).map(o=>({type:'Feature',geometry:{type:'Point',coordinates:[o.lng,o.lat]},properties:{id:o.id,name:o.name,label:o.callSign,color:!o.shiftId?'#949e99':o.stunned?'#c65b51':o.status==='on-site'?'#4b9267':o.status==='left-site'?'#c65b51':'#d59a39',state:status(o),online:o.online?'online':'offline',battery:o.battery||0}}))};}
function geojsonRoads(){return {type:'FeatureCollection',features:LOCAL_ROADS.map(r=>({type:'Feature',geometry:{type:'LineString',coordinates:r.p.map(p=>[p[1],p[0]])},properties:{name:r.name,major:Boolean(r.major)}}))};}
function libreStyle(){
 const raster=mapStyle==='satellite'?'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}':mapStyle==='topo'?'https://server.arcgisonline.com/ArcGIS/rest/services/World_Topo_Map/MapServer/tile/{z}/{y}/{x}':mapLibreBaseTileUrl();
 const sources={base:{type:'raster',tiles:[raster],tileSize:256,attribution:mapAttribution()},roads:{type:'geojson',data:geojsonRoads()},sites:{type:'geojson',data:geojsonSites()},'site-draw':{type:'geojson',data:{type:'FeatureCollection',features:[]}},'measure-line':{type:'geojson',data:{type:'FeatureCollection',features:[]}}};
 const layers=[{id:'background',type:'background',paint:{'background-color':'#0b0f17'}},{id:'base-raster',type:'raster',source:'base',paint:{'raster-opacity':1}},{id:'road-casing',type:'line',source:'roads',paint:{'line-color':'#fffdf7','line-width':['case',['get','major'],8,5],'line-opacity':.96}},{id:'local-roads',type:'line',source:'roads',paint:{'line-color':['case',['get','major'],'#c5a6ff','#cbd5e1'],'line-width':['case',['get','major'],3,1.4],'line-opacity':.92}},{id:'site-fill',type:'fill',source:'sites',paint:{'fill-color':['get','color'],'fill-opacity':.2}},{id:'site-outline',type:'line',source:'sites',paint:{'line-color':['get','color'],'line-width':2}},{id:'site-draw-line',type:'line',source:'site-draw',paint:{'line-color':'#38bdf8','line-width':3,'line-dasharray':[2,1]}},{id:'measure-line',type:'line',source:'measure-line',paint:{'line-color':'#38bdf8','line-width':3,'line-dasharray':[2,1]}}];
 if(mapStyle==='satellite'){sources.labels={type:'raster',tiles:['https://server.arcgisonline.com/ArcGIS/rest/services/Reference/World_Boundaries_and_Places/MapServer/tile/{z}/{y}/{x}'],tileSize:256,attribution:'Labels © Esri'};layers.splice(2,0,{id:'imagery-labels',type:'raster',source:'labels',paint:{'raster-opacity':.9}});}
 if(trafficOn&&trafficConfigured(S.settings)&&S.settings.trafficProvider!=='here'){sources['live-traffic']={type:'raster',tiles:[trafficTilesUrl()],tileSize:256,attribution:'Traffic © TomTom'};layers.splice(mapStyle==='satellite'?3:2,0,{id:'live-traffic-layer',type:'raster',source:'live-traffic',paint:{'raster-opacity':.95}});}
 return {version:8,sources,layers};
}
function setLocalRoadsVisible(value){const next=Boolean(value);if(localRoadsVisible===next)return;localRoadsVisible=next;if(mapLibreReady&&mapLibre){for(const id of ['road-casing','local-roads'])if(mapLibre.getLayer(id))mapLibre.setLayoutProperty(id,'visibility',localRoadsVisible?'visible':'none');refreshMapLibre();}}
function fallbackTo2DMap(message='3D map unavailable · using 2D'){mapMode='2d';mapTransition=false;$('#map3dBtn')?.classList.remove('active');$('#map2dBtn')?.classList.add('active');$('#map3d')?.classList.add('hidden');$('#map')?.classList.remove('hidden');if(!map)initMap();else map.invalidateSize();if(message)toast(message);}
function initMapLibre(){
  localRoadsVisible=true;mapLibreMarkers=new Map();mapLibreDataSignatures={units:'',sites:''};
  if(!window.maplibregl){$('#map3d').innerHTML='<div class="empty-state">3D renderer did not load. Use the 2D map or check local MapLibre files.</div>';return;}
  try{
    const center=map3dView?.center||(map?map.getCenter():{lat:-26.1037,lng:28.0585}),zoom=map3dView?.zoom||(map?map.getZoom():14);
    mapLibreReady=false;
    mapLibre=new maplibregl.Map({container:'map3d',style:libreStyle(),center:[center.lng,center.lat],zoom,pitch:map3dView?.pitch??58,bearing:map3dView?.bearing??-18,maxPitch:75,attributionControl:false,renderWorldCopies:false,fadeDuration:0,maxTileCacheSize:128,maxTileCacheZoomLevels:4,refreshExpiredTiles:true,collectResourceTiming:false});
    mapLibre.addControl(new maplibregl.AttributionControl({compact:true}),'bottom-right');
    mapLibre.addControl(new maplibregl.ScaleControl({unit:'metric'}),'top-left');
    mapLibre.on('mousemove',e=>{$('#mapCoordinates').textContent=`LAT ${e.lngLat.lat.toFixed(5)} · LNG ${e.lngLat.lng.toFixed(5)}`;});
    mapLibre.on('moveend',()=>{if(mapLibre){const c=mapLibre.getCenter();map3dView={center:{lat:c.lat,lng:c.lng},zoom:mapLibre.getZoom(),pitch:mapLibre.getPitch(),bearing:mapLibre.getBearing()};}});
    mapLibre.on('sourcedata',e=>{if(e.sourceId==='base'&&e.sourceDataType==='content'&&localRoadsVisible)setLocalRoadsVisible(false);if(e.sourceId==='live-traffic'&&e.sourceDataType==='content'&&trafficOn)setTrafficStatus('TomTom live traffic tiles loaded','ok');});let baseErrors=0,baseFallback=false;mapLibre.on('error',e=>{window.DispatchDiagnostics?.record('maplibre.error',{source:e.sourceId||'',message:e.error?.message||'MapLibre error'} ,'error');if(e.sourceId==='base'){baseErrors++;if(!baseFallback&&mapStyle==='street'&&S.settings.mapProvider!=='Local tiles'&&baseErrors>=4){baseFallback=true;const source=mapLibre.getSource('base');source?.setTiles?.(['https://tile.openstreetmap.org/{z}/{x}/{y}.png']);mapLibre.addControl(new maplibregl.AttributionControl({compact:true,customAttribution:'© OpenStreetMap contributors'}),'bottom-right');setTrafficStatus('Primary basemap unavailable · switched to OpenStreetMap','error');}else if(baseFallback&&baseErrors>=8)setLocalRoadsVisible(true);}if(e.sourceId==='live-traffic'&&trafficOn){window.DispatchDiagnostics?.record('map.traffic.tile.error',{mode:'3d',provider:'TomTom'});setTrafficStatus('TomTom traffic tiles failed · check API access and network','error');}});
    mapLibre.on('load',()=>{
      mapLibreReady=true;if(!localRoadsVisible)for(const id of ['road-casing','local-roads'])if(mapLibre.getLayer(id))mapLibre.setLayoutProperty(id,'visibility','none');syncMapLibreTrafficLayer();refreshMapLibre();if(mapTransition&&mapMode==='3d')beginMapModeTransition('3d',mapTransitionTarget);
      mapLibre.on('click','site-fill',e=>{const p=e.features?.[0]?.properties,target=p&&(p.kind==='region'?S.regions.find(x=>x.id===p.id):site(p.id));if(target)new maplibregl.Popup().setLngLat(e.lngLat).setHTML(p.kind==='region'?regionMapPopup(target):siteMapPopup(target)).addTo(mapLibre);});
      mapLibre.on('mouseenter','site-fill',()=>mapLibre.getCanvas().style.cursor='pointer');
      mapLibre.on('mouseleave','site-fill',()=>mapLibre.getCanvas().style.cursor='');
      });
    mapLibre.on('click',e=>{if(drawMode){drawPoints.push([e.lngLat.lat,e.lngLat.lng]);const src=mapLibre.getSource('site-draw');if(src&&drawPoints.length>1)src.setData({type:'Feature',geometry:{type:'LineString',coordinates:drawPoints.map(p=>[p[1],p[0]])},properties:{}});}else if(measureMode)measurePoint(e.lngLat.lat,e.lngLat.lng);});
  }catch(e){window.DispatchDiagnostics?.record('map3d.init.failed',{message:e?.message||String(e),webglSupported:MAPLIBRE_3D_SUPPORTED},'error');console.error('3D map init failed',e);try{mapLibre?.remove();}catch{}mapLibre=null;mapLibreReady=false;$('#map3d').innerHTML=`<div class="empty-state"><strong>3D view unavailable</strong>${esc(e.message||e)}<br>Using the 2D map instead.</div>`;}
}
function refreshMapLibre(){
 if(!mapLibre||!mapLibreReady)return;
 const updateSource=(id,key,data)=>{const src=mapLibre.getSource(id);if(!src)return;const signature=JSON.stringify(data);if(mapLibreDataSignatures[key]!==signature){src.setData(data);mapLibreDataSignatures[key]=signature;}};
 updateSource('sites','sites',geojsonSites());
 const used=new Set();
 const upsert=(key,coordinates,anchor,className,update,popupHtml=null,onClick=null)=>{
  let item=mapLibreMarkers.get(key);
  if(!item){const element=document.createElement('div');element.className=className;const marker=new maplibregl.Marker({element,anchor}).setLngLat(coordinates).addTo(mapLibre);item={marker,element,coordinates:null,popup:null,popupHtml:null};mapLibreMarkers.set(key,item);if(onClick)element.addEventListener('click',onClick);if(popupHtml){item.popup=new maplibregl.Popup({offset:18}).setHTML(popupHtml);item.marker.setPopup(item.popup);item.popupHtml=popupHtml;}}
  if(!item.coordinates||item.coordinates[0]!==coordinates[0]||item.coordinates[1]!==coordinates[1]){item.marker.setLngLat(coordinates);item.coordinates=[coordinates[0],coordinates[1]];}
  if(item.element.className!==className)item.element.className=className;update(item.element);
  if(popupHtml!==null&&item.popupHtml!==popupHtml){if(item.popup)item.popup.setHTML(popupHtml);else{item.popup=new maplibregl.Popup({offset:18}).setHTML(popupHtml);item.marker.setPopup(item.popup);}item.popupHtml=popupHtml;}
  used.add(key);return item;
 };
 if(localRoadsVisible)for(const road of LOCAL_ROADS){const mid=road.p[Math.floor(road.p.length/2)];upsert(`road:${road.name}`,[mid[1],mid[0]],'center','road-label libre-road-label',el=>{if(el.textContent!==road.name)el.textContent=road.name;if(el.style.display==='none')el.style.display='';});}
 else for(const road of LOCAL_ROADS){const item=mapLibreMarkers.get(`road:${road.name}`);if(item&&item.element.style.display!=='none')item.element.style.display='none';}
 for(const siteRecord of S.sites){const pts=siteRecord.coordinates,mid=pts.reduce((a,p)=>[a[0]+p[0]/pts.length,a[1]+p[1]/pts.length],[0,0]);upsert(`site:${siteRecord.id}`,[mid[1],mid[0]],'center','site-label libre-site-label',el=>{if(el.textContent!==siteRecord.name)el.textContent=siteRecord.name;});}
 for(const region of S.regions){const pts=region.coordinates,mid=pts.reduce((a,p)=>[a[0]+p[0]/pts.length,a[1]+p[1]/pts.length],[0,0]),label=`${region.name} · ZONE`;upsert(`region:${region.id}`,[mid[1],mid[0]],'center','site-label libre-site-label',el=>{if(el.textContent!==label)el.textContent=label;});}
 for(const o of S.officers){if(!Number.isFinite(o.lat)||!Number.isFinite(o.lng))continue;const color=!o.shiftId?'#949e99':o.stunned?'#c65b51':o.status==='on-site'?'#4b9267':o.status==='left-site'?'#c65b51':'#d59a39',html=`<b>${esc(initials(o.callSign))}</b><small>${esc(o.callSign)}</small>`,popupHtml=`<b>${esc(o.callSign)} · ${esc(o.name)}</b><br>${esc(status(o))} · ${esc(site(o.siteId)?.name||'No site')}<br>${o.online?'Online':'Offline'} · GPS ±${Math.round(o.accuracy||0)}m<br><button onclick="window.quickMessage('${esc(o.id)}')">Message unit</button>`;upsert(`unit:${o.id}`,[o.lng,o.lat],'bottom','libre-unit',el=>{if(el.style.background!==color)el.style.background=color;if(el.innerHTML!==html)el.innerHTML=html;},popupHtml,()=>selectMapUnit(o.id,false));}
 for(const [key,item] of mapLibreMarkers)if(!used.has(key)){item.marker.remove();mapLibreMarkers.delete(key);}
 if(trafficOn&&trafficConfigured(S.settings)&&S.settings.trafficProvider!=='here'){if(!mapLibre.getSource('live-traffic'))mapLibre.addSource('live-traffic',{type:'raster',tiles:[trafficTilesUrl()],tileSize:256,attribution:'Traffic © TomTom'});if(!mapLibre.getLayer('live-traffic-layer'))mapLibre.addLayer({id:'live-traffic-layer',type:'raster',source:'live-traffic',paint:{'raster-opacity':.95}},'road-casing');}else if(mapLibre.getLayer('live-traffic-layer')){mapLibre.removeLayer('live-traffic-layer');mapLibre.removeSource('live-traffic');}
}
function finishMapModeTransition(){if(mapSwitchTimer){clearTimeout(mapSwitchTimer);mapSwitchTimer=null;}mapTransition=false;const wrap=document.querySelector('.dashboard-map .map-wrap');wrap?.classList.remove('map-switching','switch-to-2d','switch-to-3d','map-transition-active');if(mapMode==='3d'){$('#map').classList.add('hidden');$('#map3d').classList.remove('hidden');mapLibre?.resize();if(mapLibreReady)refreshMapLibre();}else{$('#map3d').classList.add('hidden');$('#map').classList.remove('hidden');map?.invalidateSize();if(map)refreshMap();}if(trafficOn)traffic(true);}
function beginMapModeTransition(next,target){const wrap=document.querySelector('.dashboard-map .map-wrap');if(!wrap)return finishMapModeTransition();const duration=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?0:1250;wrap.classList.add('map-switching',next==='3d'?'switch-to-3d':'switch-to-2d');requestAnimationFrame(()=>{wrap.classList.add('map-transition-active');if(next==='3d'&&mapLibreReady)mapLibre?.easeTo({pitch:target.pitch,bearing:target.bearing,duration,essential:true,easing:t=>t*(2-t)});else if(next==='2d'&&mapLibreReady)mapLibre?.easeTo({pitch:0,bearing:0,duration,essential:true,easing:t=>t*(2-t)});});mapSwitchTimer=setTimeout(finishMapModeTransition,duration+160);}
function setMapMode(mode){const next=mode==='3d'?'3d':'2d';if(next==='3d'&&!MAPLIBRE_3D_SUPPORTED){fallbackTo2DMap('3D requires WebGL, unavailable in this browser environment');return;}if(next===mapMode&&!mapTransition)return;if(mapSwitchTimer){clearTimeout(mapSwitchTimer);mapSwitchTimer=null;}document.querySelector('.dashboard-map .map-wrap')?.classList.remove('map-switching','switch-to-2d','switch-to-3d','map-transition-active');mapTransition=true;const target={pitch:map3dView?.pitch??58,bearing:map3dView?.bearing??-18};mapTransitionTarget=target;if(next==='3d'){if(map){const c=map.getCenter();map3dView={center:{lat:c.lat,lng:c.lng},zoom:map.getZoom(),pitch:0,bearing:0};}$('#map').classList.remove('hidden');$('#map3d').classList.remove('hidden');if(!mapLibre)initMapLibre();else{mapLibre.resize();if(map)mapLibre.jumpTo({center:[map3dView.center.lng,map3dView.center.lat],zoom:map3dView.zoom,pitch:0,bearing:0});if(mapLibreReady)refreshMapLibre();}if(!mapLibre){mapMode='2d';$('#map2dBtn')?.classList.toggle('active',true);$('#map3dBtn')?.classList.toggle('active',false);if(!map)initMap();finishMapModeTransition();toast('3D map is unavailable; staying in 2D.',true);return;}mapMode='3d';$('#map2dBtn')?.classList.toggle('active',false);$('#map3dBtn')?.classList.toggle('active',true);if(mapLibreReady)beginMapModeTransition(next,target);}else{if(mapLibre){const c=mapLibre.getCenter();if(!map) initMap();map?.setView([c.lat,c.lng],mapLibre.getZoom(),{animate:false});}$('#map3d').classList.remove('hidden');$('#map').classList.remove('hidden');map?.invalidateSize();mapMode='2d';$('#map2dBtn')?.classList.toggle('active',true);$('#map3dBtn')?.classList.toggle('active',false);if(mapLibreReady)beginMapModeTransition(next,target);else finishMapModeTransition();}if(trafficOn)traffic(true);}
function changeMapStyle(style){mapStyle=['street','satellite','topo'].includes(style)?style:'street';try{localStorage.setItem('dispatch-map-style',mapStyle);}catch{}if(currentPage!=='overview')return;if(mapMode==='3d'){if(mapLibre){mapLibre.remove();mapLibre=null;mapLibreReady=false;}initMapLibre();}else if(map){const c=map.getCenter(),z=map.getZoom();map.remove();map=null;fallbackControl=null;markerLayer=siteLayer=sitePolygonLayer=null;leafletOfficerMarkers=new Map();leafletSitePolygons=new Map();leafletSosMarkers=new Map();initMap();map.setView(c,z);refreshMap();}}
function measurePoint(lat,lng){measurePoints.push([lat,lng]);if(mapLibreReady&&measurePoints.length>1){const src=mapLibre.getSource('measure-line');src?.setData({type:'Feature',geometry:{type:'LineString',coordinates:measurePoints.map(p=>[p[1],p[0]])},properties:{}});}if(measurePoints.length<2){toast('Select a second point to measure distance.');return;}const a=measurePoints[0],b=measurePoints[1],R=6371000,toRad=x=>x*Math.PI/180,dLat=toRad(b[0]-a[0]),dLng=toRad(b[1]-a[1]),q=Math.sin(dLat/2)**2+Math.cos(toRad(a[0]))*Math.cos(toRad(b[0]))*Math.sin(dLng/2)**2,dist=2*R*Math.atan2(Math.sqrt(q),Math.sqrt(1-q));measureMode=false;if(map){L.polyline([a,b],{color:'#254e42',weight:3,dashArray:'6 5'}).addTo(siteLayer);L.circleMarker(b,{radius:5,color:'#254e42',fillColor:'#fff',fillOpacity:1}).addTo(siteLayer);}toast(`Measured ${dist>1000?(dist/1000).toFixed(2)+' km':Math.round(dist)+' m'}`);measurePoints=[];}
